## Code Example
```kotlin
@Entity(tableName = "note")
data class Note(
    @PrimaryKey val id: Int,
    val title: String,
    val body: String,
    val timestamp: Long
)

@Dao
interface NoteDao {
    @Query("SELECT * FROM note ORDER BY timestamp DESC")
    fun getAll(): LiveData<List<Note>>

    @Query("SELECT * FROM note WHERE title LIKE '%' || :query || '%' ORDER BY timestamp DESC")
    fun searchByTitle(query: String): LiveData<List<Note>>
}

class NoteRepository(private val noteDao: NoteDao) {
    fun getAllNotes(): LiveData<List<Note>> = noteDao.getAll()
    fun searchNotes(query: String): LiveData<List<Note>> = noteDao.searchByTitle(query)
}

class NoteViewModel(private val repository: NoteRepository) : ViewModel() {
    private val _searchQuery = MutableLiveData("")

    val notes: LiveData<List<Note>> = _searchQuery.switchMap { query ->
        if (query.isBlank()) {
            repository.getAllNotes()
        } else {
            repository.searchNotes(query)
        }
    }

    fun search(query: String) {
        _searchQuery.value = query
    }
}
```

